300	function checkRateLimit(request: Request): Response | null {
301	  const ip = getClientIp(request);
302	  const { limited, resetAt } = rateLimit(`zip-check:${ip}`, 60, 60_000);
303	  if (limited) return rateLimitResponse(resetAt, CORS_HEADERS);
304	  return null;
